-- ============================================================================
-- GREATER MEMPHIS IT EMPLOYERS & 2026 ROLES DATABASE (SQLite 3 + FTS5)
-- Snapshot Date: November 2026
-- ============================================================================

PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

-- ----------------------------------------------------------------------------
-- 1. DROP EXISTING OBJECTS (CLEAN REBUILD)
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS v_company_leaderboard;
DROP VIEW IF EXISTS v_corridor_workmode_matrix;
DROP VIEW IF EXISTS v_salary_by_classification;
DROP VIEW IF EXISTS v_jobs_enriched;
DROP TRIGGER IF EXISTS job_postings_ai;
DROP TRIGGER IF EXISTS job_postings_ad;
DROP TRIGGER IF EXISTS job_postings_au;
DROP TABLE IF EXISTS jobs_fts;
DROP TABLE IF EXISTS salary_benchmarks_2026;
DROP TABLE IF EXISTS job_postings;
DROP TABLE IF EXISTS companies;

-- ----------------------------------------------------------------------------
-- 2. CREATE CORE TABLES
-- ----------------------------------------------------------------------------
CREATE TABLE companies (
    company_id INTEGER PRIMARY KEY AUTOINCREMENT,
    company_name TEXT NOT NULL UNIQUE,
    parent_or_group TEXT,
    sector TEXT NOT NULL,
    sub_market_corridor TEXT NOT NULL,
    ats_platform TEXT,
    career_portal_url TEXT,
    local_tech_roles_est INTEGER DEFAULT 1,
    total_company_open_roles_2026 INTEGER,
    is_watchlist_only INTEGER DEFAULT 0, -- 0 = Active in 118 Job Table, 1 = Watchlist
    notes TEXT
);

CREATE TABLE job_postings (
    job_id INTEGER PRIMARY KEY,
    company_id INTEGER NOT NULL,
    company_name TEXT NOT NULL,
    job_title TEXT NOT NULL,
    role_classification TEXT NOT NULL,
    seniority_level TEXT NOT NULL,
    city TEXT NOT NULL,
    state TEXT NOT NULL,
    zip_code TEXT,
    work_mode TEXT NOT NULL,
    residency_or_radius_rule TEXT,
    requisition_id TEXT,
    posting_status_2026 TEXT,
    raw_compensation TEXT,
    pay_basis_raw TEXT, -- 'Annual', 'Monthly', 'Hourly', or NULL
    annual_min_usd REAL,
    annual_max_usd REAL,
    annual_mid_usd REAL,
    tech_stack_tags TEXT,
    source_label TEXT,
    source_url TEXT NOT NULL,
    FOREIGN KEY (company_id) REFERENCES companies(company_id)
);

CREATE TABLE salary_benchmarks_2026 (
    benchmark_id INTEGER PRIMARY KEY AUTOINCREMENT,
    role_title TEXT NOT NULL,
    tier_category TEXT NOT NULL,
    low_usd REAL NOT NULL,
    mid_usd REAL NOT NULL,
    high_usd REAL NOT NULL,
    benchmark_source TEXT NOT NULL,
    region_scope TEXT DEFAULT 'Greater Memphis, TN Metro (2026)'
);

-- ----------------------------------------------------------------------------
-- 3. CREATE FTS5 FULL-TEXT SEARCH VIRTUAL TABLE & SYNC TRIGGERS
-- ----------------------------------------------------------------------------
CREATE VIRTUAL TABLE jobs_fts USING fts5(
    job_title,
    company_name,
    role_classification,
    tech_stack_tags,
    city,
    work_mode,
    posting_status_2026,
    content='job_postings',
    content_rowid='job_id'
);

CREATE TRIGGER job_postings_ai AFTER INSERT ON job_postings BEGIN
    INSERT INTO jobs_fts(rowid, job_title, company_name, role_classification, tech_stack_tags, city, work_mode, posting_status_2026)
    VALUES (new.job_id, new.job_title, new.company_name, new.role_classification, new.tech_stack_tags, new.city, new.work_mode, new.posting_status_2026);
END;

CREATE TRIGGER job_postings_ad AFTER DELETE ON job_postings BEGIN
    INSERT INTO jobs_fts(jobs_fts, rowid, job_title, company_name, role_classification, tech_stack_tags, city, work_mode, posting_status_2026)
    VALUES ('delete', old.job_id, old.job_title, old.company_name, old.role_classification, old.tech_stack_tags, old.city, old.work_mode, old.posting_status_2026);
END;

CREATE TRIGGER job_postings_au AFTER UPDATE ON job_postings BEGIN
    INSERT INTO jobs_fts(jobs_fts, rowid, job_title, company_name, role_classification, tech_stack_tags, city, work_mode, posting_status_2026)
    VALUES ('delete', old.job_id, old.job_title, old.company_name, old.role_classification, old.tech_stack_tags, old.city, old.work_mode, old.posting_status_2026);
    INSERT INTO jobs_fts(rowid, job_title, company_name, role_classification, tech_stack_tags, city, work_mode, posting_status_2026)
    VALUES (new.job_id, new.job_title, new.company_name, new.role_classification, new.tech_stack_tags, new.city, new.work_mode, new.posting_status_2026);
END;

