-- ----------------------------------------------------------------------------
-- 7. CREATE ANALYTICAL VIEWS FOR SLICING & DICING
-- ----------------------------------------------------------------------------

-- View 1: Enriched Job Postings joined with Company Sector, Corridor & ATS
CREATE VIEW v_jobs_enriched AS
SELECT
    j.job_id,
    j.company_name,
    c.parent_or_group,
    c.sector,
    c.sub_market_corridor,
    c.ats_platform,
    j.job_title,
    j.role_classification,
    j.seniority_level,
    j.city,
    j.state,
    j.zip_code,
    j.work_mode,
    j.residency_or_radius_rule,
    j.requisition_id,
    j.posting_status_2026,
    j.raw_compensation,
    j.pay_basis_raw,
    ROUND(j.annual_min_usd, 2) AS annual_min_usd,
    ROUND(j.annual_mid_usd, 2) AS annual_mid_usd,
    ROUND(j.annual_max_usd, 2) AS annual_max_usd,
    ROUND(j.annual_max_usd - j.annual_min_usd, 2) AS salary_band_spread_usd,
    j.tech_stack_tags,
    j.source_url,
    c.career_portal_url
FROM job_postings j
JOIN companies c ON j.company_id = c.company_id;

-- View 2: Role Classification Summary & Annualized Salary Metrics
CREATE VIEW v_salary_by_classification AS
SELECT
    role_classification,
    COUNT(*) AS total_postings,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM job_postings), 1) AS pct_of_total_jobs,
    COUNT(annual_mid_usd) AS postings_with_pay_data,
    ROUND(MIN(annual_min_usd), 0) AS lowest_advertised_usd,
    ROUND(AVG(annual_mid_usd), 0) AS avg_midpoint_usd,
    ROUND(MAX(annual_max_usd), 0) AS highest_advertised_usd
FROM job_postings
GROUP BY role_classification
ORDER BY total_postings DESC;

-- View 3: Sub-Market Corridor vs. Work Mode Matrix
CREATE VIEW v_corridor_workmode_matrix AS
SELECT
    c.sub_market_corridor,
    COUNT(j.job_id) AS total_cataloged_roles,
    SUM(CASE WHEN j.work_mode = 'On-site' THEN 1 ELSE 0 END) AS onsite_roles,
    SUM(CASE WHEN j.work_mode = 'Hybrid' THEN 1 ELSE 0 END) AS hybrid_roles,
    SUM(CASE WHEN j.work_mode = 'Remote' THEN 1 ELSE 0 END) AS remote_roles,
    ROUND(AVG(j.annual_mid_usd), 0) AS avg_corridor_mid_salary_usd
FROM job_postings j
JOIN companies c ON j.company_id = c.company_id
GROUP BY c.sub_market_corridor
ORDER BY total_cataloged_roles DESC;

-- View 4: Company Leaderboard (Combining Cataloged Roles, Est. Tech Roles & Total Openings)
CREATE VIEW v_company_leaderboard AS
SELECT
    c.company_name,
    c.parent_or_group,
    c.sector,
    c.sub_market_corridor,
    c.ats_platform,
    COUNT(j.job_id) AS cataloged_primary_roles,
    c.local_tech_roles_est,
    c.total_company_open_roles_2026,
    ROUND(AVG(j.annual_mid_usd), 0) AS avg_advertised_mid_usd,
    c.is_watchlist_only,
    c.career_portal_url
FROM companies c
LEFT JOIN job_postings j ON c.company_id = j.company_id
GROUP BY c.company_id
ORDER BY c.is_watchlist_only ASC, c.local_tech_roles_est DESC, cataloged_primary_roles DESC;

-- ----------------------------------------------------------------------------
-- 8. CREATE INDEXES FOR HIGH-SPEED SORTING & FILTERING
-- ----------------------------------------------------------------------------
CREATE INDEX idx_jobs_classification ON job_postings(role_classification);
CREATE INDEX idx_jobs_work_mode ON job_postings(work_mode);
CREATE INDEX idx_jobs_state_city ON job_postings(state, city);
CREATE INDEX idx_jobs_mid_salary ON job_postings(annual_mid_usd DESC);
CREATE INDEX idx_companies_sector ON companies(sector);
CREATE INDEX idx_companies_corridor ON companies(sub_market_corridor);

COMMIT;